    @EventHandler( payloadType=CreateQuoteEvent.class )
    public void handle( CreateQuoteEvent event) {
	    LOGGER.info("handling CreateQuoteEvent - " + event );
	    Quote entity = new Quote();
            entity.setQuoteId( event.getQuoteId() );
            entity.setQuoteNumber( event.getQuoteNumber() );
            entity.setValidityStart( event.getValidityStart() );
            entity.setValidityEnd( event.getValidityEnd() );
            entity.setTotalAmount( event.getTotalAmount() );
            entity.setDiscountPercent( event.getDiscountPercent() );
            entity.setTaxAmount( event.getTaxAmount() );
            entity.setShippingAmount( event.getShippingAmount() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllQuote( entity );
    }

