    /**
     * Method to retrieve the Quote via an QuotePrimaryKey.
     * @param 	id Long
     * @return 	Quote
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Quote handle( FindQuoteQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getQuoteId() );
    }
    
    /**
     * Method to retrieve a collection of all Quotes
     *
     * @param	query	FindAllQuoteQuery 
     * @return 	List<Quote> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Quote> handle( FindAllQuoteQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindQuote,
 * but only if the id matches
 *
 * @param		entity	Quote
 */
	protected void emitFindQuote( Quote entity ) {
		LOGGER.info("handling emitFindQuote" );
		
	    queryUpdateEmitter.emit(FindQuoteQuery.class,
	                            query -> query.getFilter().getQuoteId().equals(entity.getQuoteId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllQuote
	 * 
	 * @param		entity	Quote
	 */
	protected void emitFindAllQuote( Quote entity ) {
		LOGGER.info("handling emitFindAllQuote" );
		
	    queryUpdateEmitter.emit(FindAllQuoteQuery.class,
	                            query -> true,
	                            entity);
	}

